package in.onewish.web;
import in.onewish.config.Database;import jakarta.servlet.*;import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import java.io.IOException;import java.sql.*;
@WebServlet("/contact") public class ContactServlet extends HttpServlet {protected void doGet(HttpServletRequest q,HttpServletResponse s)throws ServletException,IOException{q.setAttribute("csrf",Web.csrf(q));q.setAttribute("flash",Web.takeFlash(q));q.getRequestDispatcher("/WEB-INF/views/contact.jsp").forward(q,s);}protected void doPost(HttpServletRequest q,HttpServletResponse s)throws IOException{if(!Web.validCsrf(q)){s.sendError(403);return;}String name=q.getParameter("name"),email=q.getParameter("email"),message=q.getParameter("message");if(name==null||name.trim().length()<2||name.length()>100||email==null||email.length()>190||!email.matches("[^@\\s]+@[^@\\s]+\\.[^@\\s]+")||message==null||message.trim().length()<10||message.length()>2000){Web.flash(q,"Please check your details and message.");s.sendRedirect(q.getContextPath()+"/contact");return;}try(Connection c=Database.connect();PreparedStatement p=c.prepareStatement("INSERT INTO contact_messages(name,email,message) VALUES(?,?,?)")){p.setString(1,name.trim());p.setString(2,email.trim());p.setString(3,message.trim());p.executeUpdate();Web.flash(q,"Thank you. Your note has been sent to the Onewish team.");}catch(Exception e){getServletContext().log("Contact form submission failed",e);Web.flash(q,"We couldn't send that note right now. Please try again.");}s.sendRedirect(q.getContextPath()+"/contact");}}
